// QueryHeldSummaryResponse is the measurement that makes "held is not lost" falsifiable, across all
// three pockets.
//
// The held fee is not the only thing in escrow: the BOND of a deferred dispute stays with the
// module too, as does a juror's seat while the audit it was anchored to is unresolved. Counting
// only the fee would leave "the bond stays claimable" exactly as unverifiable as "held is not lost"
// was before this query existed — an invisible orphaned fund is the class this response closes.
type QueryHeldSummaryResponse struct {
	HeldTotal         uint64 `protobuf:"varint,1,opt,name=held_total,json=heldTotal,proto3" json:"held_total,omitempty"`
	HeldCount         uint64 `protobuf:"varint,2,opt,name=held_count,json=heldCount,proto3" json:"held_count,omitempty"`
	OldestAgeBlocks   uint64 `protobuf:"varint,3,opt,name=oldest_age_blocks,json=oldestAgeBlocks,proto3" json:"oldest_age_blocks,omitempty"`
	OldestJobId       string `protobuf:"bytes,4,opt,name=oldest_job_id,json=oldestJobId,proto3" json:"oldest_job_id,omitempty"`
	BondEscrowedTotal uint64 `protobuf:"varint,5,opt,name=bond_escrowed_total,json=bondEscrowedTotal,proto3" json:"bond_escrowed_total,omitempty"`
	BondEscrowedCount uint64 `protobuf:"varint,6,opt,name=bond_escrowed_count,json=bondEscrowedCount,proto3" json:"bond_escrowed_count,omitempty"`
	// Third pocket: jurors held by the exit guard, that is, seats anchored to unresolved audits.
	// "Locked is not seized" is measured here, and any decision on allowing exit after a vote rests
	// on these numbers.
	JurorsLockedCount   uint64 `protobuf:"varint,7,opt,name=jurors_locked_count,json=jurorsLockedCount,proto3" json:"jurors_locked_count,omitempty"`
	OldestLockAgeBlocks uint64 `protobuf:"varint,8,opt,name=oldest_lock_age_blocks,json=oldestLockAgeBlocks,proto3" json:"oldest_lock_age_blocks,omitempty"`
	OldestLockJobId     string `protobuf:"bytes,9,opt,name=oldest_lock_job_id,json=oldestLockJobId,proto3" json:"oldest_lock_job_id,omitempty"`
	// SENTINEL, ALWAYS non-zero and therefore never omitted by the codec.
	//
	// proto3 omits zero-valued fields, which makes "measured zero" indistinguishable from "field not
	// present in this binary": a report could not PROVE that a zero had actually been measured. The
	// value is the number of POCKETS this binary measures (3 = fee + bond + lock). Absent from the
	// response, the binary predates the bond and lock pockets and their zeros are NOT measurements;
	// at 3 or above, a zero in fields 5 to 9 is a MEASURED zero.
	PocketsMeasured uint64 `protobuf:"varint,10,opt,name=pockets_measured,json=pocketsMeasured,proto3" json:"pockets_measured,omitempty"`
}

