// QueryServer is the server API for Query service.
type QueryServer interface {
	// Parameters queries the parameters of the module.
	Params(context.Context, *QueryParamsRequest) (*QueryParamsResponse, error)
	// GetMiner returns a single miner by its identifier.
	GetMiner(context.Context, *QueryGetMinerRequest) (*QueryGetMinerResponse, error)
	// ListMiner returns the registered miners, paginated.
	ListMiner(context.Context, *QueryAllMinerRequest) (*QueryAllMinerResponse, error)
	// GetJob returns a single job by its identifier.
	GetJob(context.Context, *QueryGetJobRequest) (*QueryGetJobResponse, error)
	// ListJob returns the jobs, paginated.
	ListJob(context.Context, *QueryAllJobRequest) (*QueryAllJobResponse, error)
	// GetPools returns the module's reward pools.
	GetPools(context.Context, *QueryGetPoolsRequest) (*QueryGetPoolsResponse, error)
	// GetCommit returns the commit published for a job.
	GetCommit(context.Context, *QueryGetCommitRequest) (*QueryGetCommitResponse, error)
	// ListCommit returns the commits, paginated.
	ListCommit(context.Context, *QueryAllCommitRequest) (*QueryAllCommitResponse, error)
	// GetBeacon returns the seed beacon of a job.
	GetBeacon(context.Context, *QueryGetBeaconRequest) (*QueryGetBeaconResponse, error)
	// ListBeacon returns the beacons, paginated.
	ListBeacon(context.Context, *QueryAllBeaconRequest) (*QueryAllBeaconResponse, error)
	// GetAvailChallenge returns the current availability challenge and its epoch. A miner answers it
	// with ProveAvailability.
	GetAvailChallenge(context.Context, *QueryGetAvailChallengeRequest) (*QueryGetAvailChallengeResponse, error)
	// CommitteeSeedHealth reports the health of the decentralized committee randomness: the seed
	// source in use, the contributor floor, the most recent decentralized seed and how many
	// validators contributed to it. The exporter derives the dendra_committee_grinding_inactive
	// metric from it — while that metric is high, grinding resistance is not actually in force.
	CommitteeSeedHealth(context.Context, *QueryCommitteeSeedHealthRequest) (*QueryCommitteeSeedHealthResponse, error)
	// AssignedCommittee returns the committee ASSIGNED to a job, READ from the chain (ADR-034).
	// A client must never re-derive the draw locally: a second implementation of consensus
	// arithmetic drifts from the first, and a client that computes a different committee than the
	// chain enforces will reject valid answers. Ask the chain instead.
	//
	// `members` is ORDERED by the consensus sort, so members[0] is the PRIMARY under optimistic
	// verification (k = 1), and a committee of size k is the k-element PREFIX of the same total order.
	//
	// The query FAILS while the job's seed is unrevealed. A draw that cannot be known must be a loud
	// stop, never an empty list indistinguishable from a job with no committee.
	AssignedCommittee(context.Context, *QueryAssignedCommitteeRequest) (*QueryAssignedCommitteeResponse, error)
	// AuditCommittee returns the JURY ANCHORED for a job — the only list `auditVerdictTally` accepts a
	// verdict from, hence the only thing standing between an honest miner and a slash.
	//
	// ⛔ IT HAD NO READER AT ALL, AND THAT COST TWO WRONG DIAGNOSES IN ONE EVENING (2026-08-11). The
	// anchor lives at `audit_committee/value/<jobId>` and was reachable only through a raw
	// `abci_query` with the key prefix hardcoded by the caller. The neighbouring query,
	// `AssignedCommittee`, answers a DIFFERENT question — who was assigned the WORK, primary first —
	// and its name invites exactly the confusion it received: a 3-member work committee was read as a
	// jury and declared unable to reach quorum, while the real jury had 12 members.
	//
	// A miner cannot otherwise learn that it is summoned, and an operator cannot audit a jury. The
	// absence of an anchor is NotFound, never an empty list: "no jury was drawn" and "the jury is
	// empty" are different facts and only one of them is about this job.
	AuditCommittee(context.Context, *QueryAuditCommitteeRequest) (*QueryAuditCommitteeResponse, error)
	// AuditDeferred returns the jobs SELECTED by the audit lottery whose OPENING was deferred,
	// because the seed was unavailable or the pool of eligible jurors was below the floor (ADR-034).
	//
	// This class cannot be derived from job state: a deferred job is indistinguishable from one the
	// lottery never sampled. It is the `deferred_no_jury` class of the audit partition, and without
	// it "zero false slashes" is satisfied trivially by auditing nothing — a green result that
	// measures nothing at all.
	AuditDeferred(context.Context, *QueryAuditDeferredRequest) (*QueryAuditDeferredResponse, error)
	// HeldSummary reports the total and the age of what the module currently WITHHOLDS.
	//
	// A sub-quorum audit defers instead of clawing back, which makes "held is not lost" the central
	// promise of that path — and a promise without a measurement cannot be checked. `held_total` and
	// `oldest_age_blocks` are the two fields able to CONTRADICT it: an age that only ever grows says
	// the network is not healing, and a total that swells says deferral is blocking escrow. This
	// query exists to produce the result that would force the opposite conclusion (ADR-033).
	HeldSummary(context.Context, *QueryHeldSummaryRequest) (*QueryHeldSummaryResponse, error)
	// ValidatorVrfKey reads back the VRF public key ANCHORED for an operator.
	//
	// WHY IT EXISTS: nothing else could read it. `MsgRegisterValidatorVrfKey` writes the key and no
	// query exposed it, so an operator could only learn whether its anchoring had landed from the
	// receipt of its own transaction — a receipt it may not have kept — or from the node's diagnostic
	// log AFTER being bonded, which is too late: an unanchored key makes a bonded validator contribute
	// nothing to the seed while every published indicator reports it healthy.
	//
	// ABSENCE IS AN ANSWER, NOT AN ERROR: an operator with no anchored key gets `anchored = false` and
	// a successful call. gRPC errors are reserved for a real failure to read, so a caller can tell
	// "there is no key" from "I could not find out" — the two must never collapse.
	ValidatorVrfKey(context.Context, *QueryValidatorVrfKeyRequest) (*QueryValidatorVrfKeyResponse, error)
}

